function openReport(){
 if(state.reportTarget==='general')return executeConfiguredReport();
 const year=state.generalYear,period=reportPeriod('general');if(!period.valid)return alert('Bitte einen gültigen Berichtszeitraum festlegen.');const allInc=state.data.incidents,allDut=state.data.duties,inc=allInc.filter(x=>period.test(x.date)),dut=allDut.filter(x=>period.test(x.date));
 const mins=dut.reduce((n,x)=>n+minutesOf(x),0),details=state.generalPdfDetail==='full';
 const byKeyword={};for(const x of inc)byKeyword[x.keyword]=(byKeyword[x.keyword]||0)+1;
 const byCategory={};for(const x of dut){const c=categoryName(x.categoryId);byCategory[c]=(byCategory[c]||0)+minutesOf(x)}
 const paid=state.data.payouts;
 const sections=[
  {title:'QUARTALE / AUSZAHLUNGEN (JAHR '+year+')',headers:['Quartal','Einsätze','Einsatzvergütung','Status'],rows:[1,2,3,4].map(q=>{const qq=allInc.filter(x=>x.date.startsWith(String(year))&&quarter(x.date)===q);return ['Q'+q,qq.length,euros(sumIncident(qq)),paid.some(x=>x.year===year&&x.quarter===q&&x.paid)?'Ausgezahlt':'Offen']})},
  {title:'EINSÄTZE NACH STICHWORT',headers:['Stichwort','Anzahl'],rows:Object.entries(byKeyword).sort((a,b)=>b[1]-a[1])},
   {title:'EINSATZPOSITIONEN',headers:['Position','Anzahl'],rows:roleSummary(inc)},
  {title:'DIENSTSTUNDEN NACH KATEGORIE',headers:['Kategorie','Stunden'],rows:Object.entries(byCategory).map(([k,v])=>[k,timeText(v)])}
 ];
 if(details){sections.push({title:'EINZELNE EINSÄTZE',headers:['Datum','Stichwort','Position','Vergütung'],rows:inc.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[dateDE(x.date),x.keyword,roleName(x),euros(incidentCents(x))])});sections.push({title:'EINZELNE DIENSTE',headers:['Zeitraum','Dienst','Zeit','Kategorie','Vergütung'],rows:dut.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[dateDE(x.date)+(inferredDutyEndDate(x)!==x.date?' – '+dateDE(inferredDutyEndDate(x)):''),x.name,x.start+'–'+x.end+' ('+timeText(minutesOf(x))+')',categoryName(x.categoryId),euros(dutyCents(x))])})}
  return showPdf(makeReport({title:'EINSATZ- UND DIENSTBERICHT',subtitle:period.label,metrics:[['Einsätze',String(inc.length)],['Dienststunden',timeText(mins)],['Einsatzvergütung',euros(sumIncident(inc))],['Dienstvergütung (separat)',euros(sumDuty(dut))],['Gesamtvergütung',euros(sumIncident(inc)+sumDuty(dut))],['Einsätze im Berichtszeitraum',String(inc.length)]],sections}),'einsatzlog-bericht-'+year+'-'+period.mode+'.pdf');
}

